import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { firstValueFrom, Observable } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { exportFilewithannot, FileListResponce } from '../../interfaces/export.interface';
import { TostbarService } from '../../../core/services/tost/tostbar.service';

@Injectable({
  providedIn: 'root'
})
export class ExportService {

  constructor(private http: HttpClient, private tost: TostbarService) { }


  async getFilelist(jFiles: string, jFolders: string): Promise<FileListResponce[]> {
    let params = new HttpParams().set('jFiles', jFiles);
    params = params.set('jFolders', jFolders);
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<FileListResponce[]>(
          `${environment.cloudUrl}${environment.coreservice}/export/getfiledata`, { params: params }
        )
      );
    } catch (error) {
      console.error(error)
      res = [];
    }
    return res;
  }


  async getExportlist(nCaseid: string, nEDid: string, nExportid: string, cSortby: string): Promise<any> {
    let params = new HttpParams().set('nCaseid', nCaseid);
    params = params.set('nEDid', nEDid);
    params = params.set('nExportid', nExportid);
    params = params.set('cSortby', cSortby);
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<any>(
          `${environment.cloudUrl}${environment.coreservice}/export/getexportdata`, { params: params }
        )
      );
    } catch (error) {
      console.error(error)
      res = [];
    }
    return res;
  }

  async clearallExport(nCaseid: string): Promise<any> {
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.post<any>(
          `${environment.cloudUrl}${environment.coreservice}/export/clearall`, { nCaseid: nCaseid }
        )
      );
      if (res && res.msg == 1) {
        this.tost.openSnackBar(res.value);
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (error) {
      this.tost.openSnackBar('Failed to clear all exports', 'E');
      console.error(error)
      return false;
    }
  }

  async deleteExport(nCaseid: string, nEDid: string, nExportid: string, cType: string): Promise<any> {
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.post<any>(
          `${environment.cloudUrl}${environment.coreservice}/export/deleteexport`, { nCaseid: nCaseid, nEDid: nEDid, nExportid: nExportid, cType: cType }
        )
      );

      if (res && res.msg == 1) {
        this.tost.openSnackBar(res.value);
        return true;
      } else {
        this.tost.openSnackBar(res.value, 'E');
        return false;
      }
    } catch (error) {
      console.error(error)
      this.tost.openSnackBar('Failed to delete export', 'E');
      return false;
    }
  }



  async exportFilewithannot(mdl: exportFilewithannot): Promise<any> {

    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.post<any>(`${environment.exportservice}/export-file/exportwithannot`, mdl));
      console.log('exportwithannot', res);
      if (res && res.msg == 1) {
        this.tost.openSnackBar(res.value);
        return res;
      } else {
        this.tost.openSnackBar(`Export Failed`, 'E');
        return res;
      }
    } catch (error) {
      console.error(error)
      this.tost.openSnackBar(`Export Failed ${error}`, 'E');
      return { msg: -1, value: 'Export Failed', error: error };
    }
  }

  createGroupFileName(fileNames: string): string {
    const fileList = fileNames.split(',').map(f => f.trim());

    if (fileList.length === 1) {
      return fileList[0];
    }

    const firstFileName = fileList[0].split('.')[0]; // Get name without extension
    const extension = fileList[0].split('.').pop();
    const otherFilesCount = fileList.length - 1;

    let groupName = `${firstFileName} and ${otherFilesCount} other${otherFilesCount > 1 ? 's' : ''}`;

    // Shorten if too long
    // if (groupName.length > 50) {
    //   groupName = groupName.substring(0, 47) + '...';
    // }

    return `${groupName}.${extension}`;
  }

  // sanitizeFileName(fileName: string): string {
  //   // Remove or replace characters that might cause issues
  //   return fileName.replace(/[<>:"/\\|?*]/g, '_');
  // }


  sanitizeFileName(fileName: string): string {
    // Replace smart quotes with standard quotes
    return fileName
      .replace(/[’‘]/g, "'") // curly quotes → straight
      .replace(/[“”]/g, '"') // curly double quotes → straight
      .replace(/[<>:"/\\|?*]/g, '_') // invalid filename characters → _
      .trim();

  }

  async downloadFile(cPath: string, filenames: string) {
    try {
      const groupFileName = this.createGroupFileName(filenames);
      const sanitizedFileName = this.sanitizeFileName(groupFileName);
      const shortenedFileName = this.shortenFileName(sanitizedFileName, 100, cPath);

      const downloadUrl = `${environment.exportservice}/download?cPath=${encodeURIComponent(cPath)}&cFilename=${encodeURIComponent(shortenedFileName)}`;

      const link = document.createElement('a');
      link.href = downloadUrl;

      // Add event listeners
      link.addEventListener('load', () => {
        console.log('Download started');
      });

      link.addEventListener('error', () => {
        console.error('Error downloading file');
      });

      // Append the link to the body
      document.body.appendChild(link);

      // Trigger the click event
      link.click();

      // Remove the link from the document
      document.body.removeChild(link);

    } catch (error) {
      console.error('Error initiating download:', error);
    }
  }

  shortenFileName(fileName: string, maxLength: number = 50, cPath: string): string {
    let extension = fileName.split('.').pop();

    // If no extension in filename, extract it from the path
    const pathExtension = cPath.split('.').pop();
    if (extension.toUpperCase() != pathExtension.toUpperCase()) {
      if (pathExtension) {
        extension = pathExtension;
        fileName += `.${extension}`;
      }
    } else if (fileName.split('.').length > 2) {
      // Handle multiple dots in filename
      const parts = fileName.split('.');
      extension = parts.pop();
      fileName = parts.join('.') + '.' + extension;
    } else {
      extension = extension || '';
    }

    const name = fileName.substring(0, fileName.length - extension.length - 1);

    if (name.length + extension.length + 1 <= maxLength) {
      return fileName;
    }

    const halfMax = Math.floor((maxLength - extension.length - 4) / 2);
    const firstHalf = name.slice(0, halfMax);
    const secondHalf = name.slice(-halfMax);

    return `${firstHalf}...${secondHalf}.${extension}`;
  }

  async retryExport(nExportid: number): Promise<any> {
    try {
      const params = new HttpParams().set('nExportid', nExportid.toString());
      const res = await firstValueFrom(
        this.http.post<any>(
          `${environment.exportservice}/export-file/retryexport`, params
        )
      );

      if (res.msg != 1) {
        throw new Error(res.value || 'Failed to retry export');
      }

      this.tost.success(res.value || 'Export retried successfully');
      return true;
    } catch (error: any) {
      this.tost.openSnackBar(error.message || 'Failed to retry exports', 'E');
      console.error(error);
      return false;
    }
  }
}
